/**
 * PROJECT IMPACT ANALYSIS ENGINE - v8.13
 * FIX: Fixed column name case-sensitivity and input reference.
 * FILTER: (Percentage Complete < 100) AND (Assigned To match found).
 */

// 1. DATA SOURCES
// If this still returns nothing, replace $input.all() with $("Node_Name").all()
const allRows = $input.all(); 
const directory = $("Fetched Directory").all(); 

const filteredOutput = [];
const today = new Date();

// Create the Directory Lookup Map
const phoneDirectory = {};
directory.forEach(item => {
    // We check both "Assigned to" and "Assigned To" just in case
    const nameData = item.json["Assigned to"] || item.json["Assigned To"] || "";
    const name = String(nameData).trim().toLowerCase();
    const phone = item.json["Phone no"] !== undefined ? String(item.json["Phone no"]).trim() : "";
    if (name && phone) phoneDirectory[name] = phone;
});

// 2. PROCESS EVERY ROW
for (const item of allRows) {
    const row = item.json;

    // Support different possible column casings from Smartsheet
    const pctKey = row["Percentage Complete"] !== undefined ? "Percentage Complete" : "percentage complete";

    if (row[pctKey] !== undefined) {
        let val = row[pctKey];
        let pctNum = (typeof val === 'string') ? parseFloat(val.replace('%', '').trim()) : (val <= 1 ? val * 100 : val);

        // REQUIREMENT 1: Only rows where percentage < 100
        if (pctNum >= 100) continue; 

        // --- PRESERVED v8.1 LOGIC ---
        const formatDate = (dateVal) => {
            if (!dateVal || dateVal === "null" || dateVal === null) return "TBD";
            const d = new Date(dateVal);
            return isNaN(d) ? "TBD" : `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
        };

        const bs = row["Baseline Start"] ? new Date(row["Baseline Start"]) : null;
        const bf = row["Baseline Finish"] ? new Date(row["Baseline Finish"]) : null;
        const as = row["Start"] ? new Date(row["Start"]) : null;

        let slippageDays = (bs && as && as > bs) ? Math.round((as - bs) / 86400000) : 0;
        const daysSinceStart = as ? Math.max(1, Math.floor((today - as) / 86400000)) : 1;
        const dailyVelocity = pctNum / daysSinceStart; 
        const remainingPct = 100 - pctNum;
        const daysToFinish = dailyVelocity > 0 ? (remainingPct / dailyVelocity) : 0;
        const projectedDate = new Date(today.getTime() + (daysToFinish * 86400000));
        let totalProjectedDelay = (bf && projectedDate > bf) ? Math.round((projectedDate - bf) / 86400000) : 0;

        let statusLabel = (pctNum < 100 && bf < today) ? "🔴 OVERDUE" : "🚀 ACTIVE";
        if (as > today && pctNum === 0) {
            statusLabel = "📅 FUTURE";
            slippageDays = 0; 
            totalProjectedDelay = 0;
        }

        // --- REQUIREMENT 2: MATCH ASSIGNED TO WITH GOOGLE SHEET ---
        const rawNames = row["Assigned To"] || row["assigned to"] || "";
        const nameList = String(rawNames).split(',').map(n => n.trim());

        let phoneList = [];
        let validNames = [];

        for (const name of nameList) {
            if (!name || name === "null") continue;
            const empLower = name.toLowerCase();
            const foundPhone = phoneDirectory[empLower];

            if (foundPhone) {
                const cleanNumber = String(foundPhone).replace(/\D/g, '');
                phoneList.push(cleanNumber + "@s.whatsapp.net");
                validNames.push(name);
            }
        }

        // --- FINAL OUTPUT GATE ---
        // Only return if Phone match found AND percentage < 100
        if (phoneList.length > 0) {
            filteredOutput.push({
                json: {
                    ...row, 
                    "Percentage_Complete_Clean": pctNum + "%",
                    "Clean_Phone": phoneList.join(','), 
                    "Slippage_Days": slippageDays,
                    "Projected_Delay": totalProjectedDelay,
                    "Forecasted_Finish": formatDate(projectedDate),
                    "Simple_Pace": totalProjectedDelay > 5 ? "🔴 CRITICAL SLOWDOWN" : (totalProjectedDelay > 0 ? "🟡 SLIGHTLY BEHIND" : "🟢 ON TRACK"),
                    "Impact_Score": (row["Critical"] === true || totalProjectedDelay > 7) ? "High" : "Medium",
                    "Display_BS": formatDate(bs),
                    "Display_BF": formatDate(bf),
                    "Display_AS": formatDate(as),
                    "Comments_Clean": (!row["Comments"] || row["Comments"] === "null") ? "No feedback yet" : row["Comments"],
                    "Status_Clean": statusLabel,
                    "Assigned_Lead": validNames.join(', ')
                }
            });
        }
    }
}

return filteredOutput;

/**
 * EMPLOYEE AGGREGATOR v8.5
 * FIX: Splits comma-separated Clean_Phone strings to ensure individual messaging.
 * GOAL: One output item per unique phone number.
 */
const allRows = $input.all();
const groupedByEmployee = {};
const today = new Date();
const next48Hours = new Date();
next48Hours.setDate(today.getDate() + 2);

for (const item of allRows) {
    const row = item.json;

    // --- 🟢 FIX: SPLIT MULTIPLE PHONES INTO INDIVIDUALS 🟢 ---
    const rawPhones = String(row["Clean_Phone"] || "");
    if (!rawPhones || rawPhones === "MANUAL_CHECK_NEEDED") continue;

    // Split "923...,923..." into an array of individual JIDs
    const individualPhones = rawPhones.split(',').map(p => p.trim());

    for (const phone of individualPhones) {
        if (!phone) continue;

        // Initialize group for this specific phone number
        if (!groupedByEmployee[phone]) {
            groupedByEmployee[phone] = {
                phone: phone,
                name: (row["Assigned_Lead"] || "Team Member").split(',')[0].trim(),
                totalAssigned: 0,
                activeCount: 0,
                pendingCount: 0,
                taskList: "" 
            };
        }

        const emp = groupedByEmployee[phone];
        emp.totalAssigned++;

        // 1. Progress Stats
        const pctNum = parseFloat(String(row["Percentage_Complete_Clean"]).replace('%', '')) || 0;
        if (pctNum === 0) emp.pendingCount++;
        else if (pctNum > 0 && pctNum < 100) emp.activeCount++;

        // 2. Date Handling
        let as = new Date(row["Start"]);
        let af = new Date(row["Finish"]);
        let actualStart = (as < af) ? as : af;
        let actualFinish = (as < af) ? af : as;

        // 3. Status Logic
        let statusLabel = "";
        if (pctNum < 100 && actualFinish < today) {
            statusLabel = "🔴 OVERDUE";
        } else if (pctNum < 100 && actualFinish <= next48Hours && actualFinish >= today) {
            statusLabel = "⏳ DUE SOON";
        } else if (actualStart > today && pctNum === 0) {
            statusLabel = "📅 FUTURE";
        } else {
            statusLabel = "🚀 ACTIVE";
        }

        // 4. Formatting Dates for Display
        const fDate = (d) => (d && !isNaN(d)) ? d.toISOString().split('T')[0] : "TBD";
        const bStart = row["Display_BS"] || "TBD";
        const bFinish = row["Display_BF"] || "TBD";
        const aStart = fDate(actualStart);
        const aFinish = fDate(actualFinish);

        const slip = row["Slippage_Days"] || 0;
        const comment = (!row["Comments_Clean"] || row["Comments_Clean"] === "null") ? "No feedback" : row["Comments_Clean"];

        // 5. Task Entry
        emp.taskList += `\n${statusLabel} | *${row["Task id"] || 'N/A'}*: ${row["Task Name"]}\n` +
                        `    🏁 *Baseline:* ${bStart} to ${bFinish}\n` +
                        `    🏃 *Actual:* ${aStart} to ${aFinish}\n` +
                        `    📊 Progress: ${row["Percentage_Complete_Clean"]} | 🚩 Slippage: ${slip}d\n` +
                        `    💬 Last comment: "${comment}"\n`;
    }
}

// Return as individual items so n8n triggers the WhatsApp node once per person
return Object.values(groupedByEmployee).map(emp => ({ json: emp }));
